import { LightTheme } from "@mendix/ide-theming/global/gen/DesignSystemTokens";
import React from "react";
import styled from "styled-components";

const StyledPageContainer = styled.div`
    display: flex;
    flex-direction: column;
    min-height: 100%;
    text-align: left;
    padding: 16px;
    background: ${(props) => (props.theme === LightTheme ? props.theme.colorsAccentWhite : "initial")};
    position: relative;
`;

export const PageContainer: React.FC<{ children: React.ReactNode; className?: string }> = ({ children, className }) => (
    <StyledPageContainer className={className}>{children}</StyledPageContainer>
);

const StyledPageContainerDialog = styled(StyledPageContainer)`
    padding: 8px;
`;

export const PageContainerDialog: React.FC<{ children: React.ReactNode; className?: string }> = ({
    children,
    className,
}) => <StyledPageContainerDialog className={className}>{children}</StyledPageContainerDialog>;

export const PageContent = styled.div`
    width: round(calc(100% - 1px), 2px);
    display: flex;
    flex-direction: row;
    min-height: 100%;
    gap: 24px;
`;

export const ContentColumn = styled.div`
    flex: 1;
    min-width: 360px;
    max-width: 720px;
    display: flex;
    flex-direction: column;
    gap: 8px;

    ${StyledPageContainerDialog} & {
        max-width: none;
    }
`;

export const ContentColumnSmall = styled(ContentColumn)`
    max-width: 600px;
`;

export const ContentColumnLarge = styled(ContentColumn)`
    max-width: 1440px;
`;

export const FlexColumn = styled.div`
    display: flex;
    flex-direction: column;
    gap: 8px;
    width: 100%;
`;
