import { useState, useEffect, ReactNode } from "react";
import { ThemeProvider } from "styled-components";
import { LightTheme, DarkTheme, Theme } from "@mendix/ide-theming/global/gen/DesignSystemTokens";
import { GlobalStyle } from "@mendix/ide-theming/global/GlobalStyle";
import { getUserTheme } from "../../utils/userPreferences";
import { StudioProApi } from "@mendix/extensions-api";

type AppThemeProviderProps = {
    studioPro: StudioProApi;
    children: ReactNode;
};

const AppThemeProvider = ({ studioPro, children }: AppThemeProviderProps) => {
    const [userTheme, setUserTheme] = useState(LightTheme);

    useEffect(() => {
        (async function () {
            const currentTheme: Theme = (await getUserTheme(studioPro)) === "Dark" ? DarkTheme : LightTheme;
            setUserTheme(currentTheme);
        })();
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, []);

    return (
        <ThemeProvider theme={userTheme}>
            <GlobalStyle theme={userTheme}></GlobalStyle>
            {children}
        </ThemeProvider>
    );
};

export default AppThemeProvider;
